  (* [comment removed for export] *)
  (* [comment removed for export] *)
  assert (FZ : (n = 0 \/ (0 <= estart E (SA db dk) /\ estart E (SA db dk) + n <= 2 ^ 64)) ->
               know_ok SEGS E (wbytes M s (repeat (Z_to_bv 8 c) (Z.to_nat n))) fz).
  { intros [Hz|[Hlo Hhi]]; [rewrite Hz; exact HKfz|].
    destruct (Z.eq_dec n 0) as [Hz|Hnz]; [rewrite Hz; exact HKfz|].
    assert (Hd : Forall (fun h => APS.hull_apart E h (estart E (SA db dk)) n) hs).
    { rewrite fill_in_wins_eq in Hap. unfold fill_in_wins_ref in Hap. destruct hs as [|h0 hs']; [constructor|]. cbn [hs_nil] in Hap.
